What does the following C function return for f(7)?

int f(int n) {
    if (n <= 1) return 1;
    return n * f(n - 2);
}

What is printed by the following C code?

int a[] = {10, 20, 30, 40, 50};
int *p = a + 1;
printf("%d", *(p + 2) + p[-1]);

What is printed by the following C program?

int g(void) { static int c = 0; c += 2; return c; }
int main(void) {
    int s = 0;
    for (int i = 0; i < 3; i++) s += g();
    printf("%d", s);
    return 0;
}

